  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "Felbamate has virtually complete absolute oral bioavailability in non-elderly adults, demonstrating that a small, non-basic, orally absorbed drug can achieve F well above 20%; this supports high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Roquinimex, a 4-hydroxy-2-oxo heterocycle with an acidic enol similar to the query's 4-hydroxycoumarin, shows complete oral bioavailability in healthy volunteers, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Ketoprofen, an acidic lipophilic drug, has absolute oral bioavailability of at least 92% in humans, supporting high F for the similarly acidic, lipophilic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Diflunisal, a salicylic acid derivative, has absolute oral bioavailability of 89.5%, supporting high F for the acidic aromatic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Baclofen, despite a zwitterionic polar structure, has absolute oral bioavailability of 85.8%, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Baicalein has low oral bioavailability, but as a polyphenolic flavone with poor solubility and extensive conjugation, it is not transferable to the 4-hydroxycoumarin query and does not outweigh the high-F analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is warfarin, a 4-hydroxycoumarin anticoagulant with essentially complete oral absorption in humans. Multiple structurally relevant high-bioavailability analogues (felbamate, roquinimex, ketoprofen, diflunisal, baclofen) support F ≥20%; the only low-F analogue (baicalein) is a polyphenolic flavone with poor transferability. Prediction: high.",
